@extends('layouts.app')
@section('title', '在线地图')
@section('content')
<div class="space-y-5"><section class="card border-0 bg-gradient-to-br from-emerald-600 to-cyan-700 p-5 text-white"><h1 class="text-2xl font-bold">服务器在线地图</h1><p class="mt-1 text-emerald-50">拖动浏览 · 滚轮缩放 · Dynmap 原生瓦片</p></section><section class="card overflow-hidden"><div class="flex flex-wrap gap-3 border-b p-4"><select id="world" class="rounded border p-2"></select><select id="map" class="rounded border p-2"></select><button id="reset" class="rounded bg-primary-50 px-3 text-primary-700">居中</button><span id="hint" class="text-sm text-slate-500"></span></div><div id="view" class="relative h-[70vh] min-h-[520px] overflow-hidden bg-slate-900 touch-none"><div id="layer" class="absolute" style="transform-origin:0 0"></div><div class="absolute bottom-3 left-3 rounded bg-black/60 px-2 py-1 text-xs text-white">拖动移动 · 双指/滚轮缩放</div></div></section></div>
<style>.tile{position:absolute;width:128px;height:128px;display:block}</style>
<script>
(()=>{const ws=document.querySelector('#world'),ms=document.querySelector('#map'),view=document.querySelector('#view'),layer=document.querySelector('#layer'),hint=document.querySelector('#hint');let worlds=[],tiles=[],state={x:0,y:0,s:1},drag=null;const esc=encodeURIComponent;function apply(){layer.style.transform=`translate(${state.x}px,${state.y}px) scale(${state.s})`}function reset(){if(!tiles.length)return;const xs=tiles.map(t=>t.x),ys=tiles.map(t=>t.y),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys);state.s=Math.min(1,view.clientWidth/((maxx-minx+1)*128),view.clientHeight/((maxy-miny+1)*128));state.x=(view.clientWidth-(maxx-minx+1)*128*state.s)/2-minx*128*state.s;state.y=(view.clientHeight-(maxy-miny+1)*128*state.s)/2-miny*128*state.s;apply()}async function draw(){const w=worlds[ws.value],m=w.maps[ms.value],map=m.prefix||m.name;hint.textContent='读取瓦片…';const d=await fetch(`/map/tiles-manifest/${esc(w.name)}/${esc(map)}?_=${Date.now()}`).then(r=>r.json());tiles=(d.tiles||[]).map((f,i)=>{const a=f.match(/(-?\d+)_(-?\d+)\.(?:png|jpe?g|webp)$/i);return {f,x:a?+a[1]:i%20,y:a?+a[2]:Math.floor(i/20)}});layer.innerHTML=tiles.map(t=>`<img class="tile" style="left:${t.x*128}px;top:${t.y*128}px" src="/map/tile-file?world=${esc(w.name)}&map=${esc(map)}&path=${esc(t.f)}">`).join('');hint.textContent=`${w.name} / ${map} · ${tiles.length} 块`;reset()}function maps(){const w=worlds[ws.value];ms.innerHTML=w.maps.map((m,i)=>`<option value="${i}">${m.title||m.name||m.prefix}</option>`).join('');draw()}async function boot(){const d=await fetch('/map/data?_='+Date.now()).then(r=>r.json());worlds=(d.data.worlds||[]).filter(w=>w.name!=='faces');ws.innerHTML=worlds.map((w,i)=>`<option value="${i}">${w.title||w.name}</option>`).join('');maps()}ws.onchange=maps;ms.onchange=draw;document.querySelector('#reset').onclick=reset;view.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,ox:state.x,oy:state.y};view.setPointerCapture(e.pointerId)};view.onpointermove=e=>{if(drag){state.x=drag.ox+e.clientX-drag.x;state.y=drag.oy+e.clientY-drag.y;apply()}};view.onpointerup=()=>drag=null;view.onwheel=e=>{e.preventDefault();const r=view.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top,n=Math.max(.15,Math.min(3,state.s*(e.deltaY<0?1.18:.85)));state.x=mx-(mx-state.x)*n/state.s;state.y=my-(my-state.y)*n/state.s;state.s=n;apply()};boot().catch(e=>hint.textContent=e.message)})()
</script>
@endsection